import re
import os


def task_func(request):
    if not isinstance(request, str):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    request_line = request.split("\r\n", 1)[0]
    if "\n" in request_line:
        request_line = request_line.split("\n", 1)[0]
    request_line = request_line.rstrip("\r")

    match = re.fullmatch(
        r"GET[ \t]+/([^\s?]+)(?:\?[^\s]*)?[ \t]+HTTP/\d+(?:\.\d+)?",
        request_line,
    )
    if not match:
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid request"

    filename = match.group(1)

    if (
        "\x00" in filename
        or "\\" in filename
        or os.path.isabs(filename)
        or os.path.splitdrive(filename)[0]
    ):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid filename"

    normalized = os.path.normpath(filename)
    if normalized in (".", "..") or normalized.startswith(
        (".." + os.sep, "../")
    ):
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid filename"

    root = os.path.realpath(os.getcwd())
    path = os.path.realpath(normalized)

    try:
        if os.path.commonpath((root, path)) != root:
            return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid filename"
    except ValueError:
        return "HTTP/1.1 400 Bad Request\r\n\r\nInvalid filename"

    if not os.path.isfile(normalized):
        return "HTTP/1.1 404 Not Found\r\n\r\nFile not found"

    try:
        with open(normalized, "r", encoding="utf-8") as file:
            content = file.read()
    except (OSError, UnicodeError):
        return (
            "HTTP/1.1 500 Internal Server Error"
            "\r\n\r\nUnable to read file"
        )

    return (
        "HTTP/1.1 200 OK\r\n"
        f"Content-Length: {len(content.encode('utf-8'))}\r\n"
        "\r\n"
        f"{content}"
    )

