import numpy as np
import ast


def task_func(csv_file):
    df = pd.read_csv(csv_file)

    required_columns = {"email", "list"}
    missing_columns = required_columns.difference(df.columns)
    if missing_columns:
        raise ValueError(
            f"Missing required column(s): {', '.join(sorted(missing_columns))}"
        )

    def parse_list(value):
        if isinstance(value, (list, tuple, np.ndarray)):
            return list(value)

        if value is None or (isinstance(value, float) and np.isnan(value)):
            return []

        try:
            parsed = ast.literal_eval(str(value))
        except (ValueError, SyntaxError) as exc:
            raise ValueError(
                "Values in the 'list' column must represent lists."
            ) from exc

        if not isinstance(parsed, (list, tuple)):
            raise ValueError("Values in the 'list' column must represent lists.")

        return list(parsed)

    df["list"] = df["list"].apply(parse_list)
    df["sum"] = df["list"].apply(lambda values: np.sum(values) if values else np.nan)
    df["mean"] = df["list"].apply(lambda values: np.mean(values) if values else np.nan)
    df["std"] = df["list"].apply(lambda values: np.std(values) if values else np.nan)

    histogram = sns.histplot(data=df, x="mean")

    return df[["email", "list", "sum", "mean", "std"]], histogram

