import pandas as pd
import numpy as np
import itertools
from datetime import datetime, timedelta
import seaborn as sns


def task_func(df, fruits=None, days=None, seed=None, sales_lower_bound=1, sales_upper_bound=50):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("'df' must be a pandas DataFrame")

    if not df.empty:
        raise ValueError("'df' must be empty")

    if sales_lower_bound >= sales_upper_bound:
        raise ValueError(
            "'sales_lower_bound' must be less than 'sales_upper_bound'"
        )

    if fruits is None:
        fruits = ["apple", "banana", "orange"]

    if days is None:
        days = 7

    if isinstance(days, bool) or not isinstance(days, int):
        raise TypeError("'days' must be a non-negative integer")

    if days < 0:
        raise ValueError("'days' must be non-negative")

    fruits = list(fruits)
    start_date = datetime.now().date()
    dates = [
        start_date + timedelta(days=offset)
        for offset in range(days)
    ]

    combinations = list(itertools.product(fruits, dates))
    rng = np.random.default_rng(seed)
    sales = rng.integers(
        low=sales_lower_bound,
        high=sales_upper_bound,
        size=len(combinations),
    )

    generated_data = pd.DataFrame(
        [
            {"fruit": fruit, "date": date, "sales": sale}
            for (fruit, date), sale in zip(combinations, sales)
        ],
        columns=["fruit", "date", "sales"],
    )

    updated_df = pd.concat(
        [df.copy(), generated_data],
        ignore_index=True,
    )

    plot = sns.catplot(
        data=updated_df,
        x="fruit",
        y="sales",
        kind="box",
    )

    return updated_df, plot

