from urllib.parse import urlparse

# Constants
CSV_FILE_PATH = 'scraped_data.csv'


def task_func(url):
    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")

    url = url.strip()
    parsed_url = urlparse(url)
    if parsed_url.scheme not in ("http", "https") or not parsed_url.netloc:
        raise ValueError("url must be a valid HTTP or HTTPS URL")

    request = urllib.request.Request(
        url,
        headers={"User-Agent": "Mozilla/5.0"}
    )

    with urllib.request.urlopen(request, timeout=20) as response:
        content = response.read()
        charset = response.headers.get_content_charset() or "utf-8"

    try:
        html = content.decode(charset, errors="replace")
    except LookupError:
        html = content.decode("utf-8", errors="replace")

    soup = BeautifulSoup(html, "html.parser")

    for element in soup(["script", "style", "noscript", "template"]):
        element.decompose()

    def normalize(value):
        return " ".join(value.split())

    rows = []
    for table in soup.find_all("table"):
        for row in table.find_all("tr"):
            cells = [
                normalize(cell.get_text(" ", strip=True))
                for cell in row.find_all(["th", "td"])
            ]
            if cells:
                rows.append(cells)

    if rows:
        column_count = max(len(row) for row in rows)
        header = [
            f"column_{index}"
            for index in range(1, column_count + 1)
        ]
        output_rows = [
            row + [""] * (column_count - len(row))
            for row in rows
        ]
    else:
        text_rows = []
        for element in soup.find_all(
            ["h1", "h2", "h3", "h4", "h5", "h6", "p", "li", "a"]
        ):
            if element.has_attr("hidden"):
                continue
            if element.get("aria-hidden", "").lower() == "true":
                continue

            text = normalize(element.get_text(" ", strip=True))
            if text and text not in text_rows:
                text_rows.append(text)

        header = ["text"]
        output_rows = [[text] for text in text_rows]

    directory = os.path.dirname(CSV_FILE_PATH)
    if directory:
        os.makedirs(directory, exist_ok=True)

    with open(CSV_FILE_PATH, "w", newline="", encoding="utf-8") as csv_file:
        writer = csv.writer(csv_file)
        writer.writerow(header)
        writer.writerows(output_rows)

    return CSV_FILE_PATH

import numpy as np
import matplotlib.pyplot as plt

# Constants
CITIES = [
    'New York', 'London', 'Beijing', 'Tokyo', 'Sydney',
    'Paris', 'Berlin', 'Moscow', 'Madrid', 'Rome'
]


def task_func(city_dict, max_range=1000000, seed=0):
    if not isinstance(city_dict, dict):
        raise TypeError("city_dict must be a dictionary")

    if isinstance(max_range, bool) or not isinstance(max_range, (int, np.integer)):
        raise TypeError("max_range must be a positive integer")
    if max_range <= 0:
        raise ValueError("max_range must be a positive integer")

    np.random.seed(seed)
    populations = {}

    for city in city_dict.values():
        if not isinstance(city, str):
            raise TypeError("city names must be strings")

        if city not in populations:
            populations[city] = (
                int(np.random.randint(1, max_range + 1))
                if city in CITIES
                else -1
            )

    _, ax = plt.subplots()
    ax.bar(populations.keys(), populations.values())
    ax.set_xlabel("City")
    ax.set_ylabel("Population")
    ax.set_title("City Populations")
    ax.tick_params(axis="x", rotation=45)
    ax.figure.tight_layout()

    return populations, ax

