import json
import csv
import os
import base64


def task_func(raw_string, filename, output_dir):
    if not isinstance(raw_string, str):
        raise TypeError("raw_string must be a string")
    if not isinstance(filename, str):
        raise TypeError("filename must be a string")
    if not isinstance(output_dir, str):
        raise TypeError("output_dir must be a string")
    if not filename or filename in {".", ".."}:
        raise ValueError("filename must not be empty")
    if os.path.basename(filename) != filename:
        raise ValueError("filename must not contain path components")

    decoded = base64.b64decode(raw_string, validate=True).decode("utf-8")
    data = json.loads(decoded)

    if isinstance(data, dict):
        rows = [data]
    elif isinstance(data, list) and all(isinstance(item, dict) for item in data):
        rows = data
    else:
        raise ValueError("JSON must contain a dictionary or a list of dictionaries")

    fieldnames = []
    for row in rows:
        for key in row:
            if key not in fieldnames:
                fieldnames.append(key)

    os.makedirs(output_dir, exist_ok=True)
    file_path = os.path.join(output_dir, filename)

    with open(file_path, "w", encoding="utf-8", newline="") as csv_file:
        writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
        if fieldnames:
            writer.writeheader()
            writer.writerows(rows)

    return file_path

import pandas as pd
import re
import random


def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    product_names = ["Apple", "Banana", "Orange", "Pear", "Grape"]

    rng = random.Random(seed)
    code_to_product = {}
    rows = []

    for line_number, line in enumerate(s.splitlines(), start=1):
        if not line.strip():
            continue

        parts = re.split(r"\s+", line.strip(), maxsplit=4)
        if len(parts) != 5:
            raise ValueError(
                f"Line {line_number} must contain ID, quantity, code, price, "
                "and description."
            )

        product_id, quantity, code, price, description = (
            part.rstrip() for part in parts
        )

        try:
            product_id = int(product_id)
            quantity = int(quantity)
            price = int(price)
        except ValueError as exc:
            raise ValueError(
                f"Line {line_number} contains invalid numeric fields."
            ) from exc

        if code not in code_to_product:
            code_to_product[code] = rng.choice(product_names)

        rows.append(
            {
                "ID": product_id,
                "Quantity": quantity,
                "Code": code,
                "Price": price,
                "Product": code_to_product[code],
                "Description": description,
            }
        )

    data_df = pd.DataFrame(rows, columns=columns)
    data_df = data_df.astype(
        {"ID": "int64", "Quantity": "int64", "Price": "int64"}
    )
    return data_df

import itertools
import math
from pandas import Series


def task_func(elements, subset_size, top_n=2):
    if subset_size < 0 or subset_size > len(elements):
        return 1, Series(dtype=int)

    if subset_size == 0:
        return 1, Series([0]) if top_n > 0 else Series(dtype=int)

    subset_sums = [
        sum(subset)
        for subset in itertools.combinations(elements, subset_size)
    ]

    product = math.prod(subset_sums)
    top_sums = Series(sorted(subset_sums, reverse=True)[:max(0, top_n)])

    return product, top_sums

import subprocess
import os
import signal
import time


def task_func(process_name: str) -> int:
    if not process_name:
        return 0

    target = os.path.basename(process_name)
    current_pid = os.getpid()
    pids = []

    try:
        if os.name == "nt":
            result = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                check=False,
            )

            for line in result.stdout.splitlines():
                fields = [field.strip().strip('"') for field in line.split(",")]
                if len(fields) < 2:
                    continue
                if fields[0].casefold() != target.casefold():
                    continue
                try:
                    pid = int(fields[1])
                except ValueError:
                    continue
                if pid != current_pid:
                    pids.append(pid)
        else:
            result = subprocess.run(
                ["ps", "-eo", "pid=,comm="],
                capture_output=True,
                text=True,
                check=False,
            )

            for line in result.stdout.splitlines():
                parts = line.strip().split(None, 1)
                if len(parts) != 2:
                    continue
                try:
                    pid = int(parts[0])
                except ValueError:
                    continue
                if os.path.basename(parts[1]) == target and pid != current_pid:
                    pids.append(pid)
    except (OSError, subprocess.SubprocessError):
        time.sleep(1)
        return 0

    stopped = 0
    for pid in pids:
        try:
            os.kill(pid, signal.SIGTERM)
            stopped += 1
        except OSError:
            continue

    time.sleep(1)
    return stopped

import os
