# Constants
BACKUP_DIR = '/tmp/backup'


def get_unique_backup_dir():
    return "/fake/backup/path"


def task_func(directory):
    backup_dir = get_unique_backup_dir()
    errors = []

    if not os.path.isdir(directory):
        errors.append(f"Source directory does not exist: {directory}")
        return backup_dir, errors

    try:
        os.makedirs(backup_dir, exist_ok=False)
    except FileExistsError:
        errors.append(f"Backup directory already exists: {backup_dir}")
        return backup_dir, errors
    except OSError as exc:
        errors.append(f"Could not create backup directory: {exc}")
        return backup_dir, errors

    try:
        entries = os.listdir(directory)
    except OSError as exc:
        errors.append(f"Could not list source directory: {exc}")
        return backup_dir, errors

    for entry in entries:
        source = os.path.join(directory, entry)
        destination = os.path.join(backup_dir, entry)

        try:
            if os.path.isdir(source) and not os.path.islink(source):
                shutil.copytree(source, destination, symlinks=True)
                shutil.rmtree(source)
            else:
                shutil.copy2(source, destination, follow_symlinks=False)
                os.remove(source)
        except (OSError, shutil.Error) as exc:
            errors.append(f"{source}: {exc}")

    return backup_dir, errors

