import subprocess
import os
import sys
import glob


def task_func(directory_path):
    patterns = (
        os.path.join(directory_path, "*.bat"),
        os.path.join(directory_path, "*.BAT"),
    )

    bat_files = []
    seen = set()

    for pattern in patterns:
        for file_path in sorted(glob.glob(pattern)):
            normalized_path = os.path.normcase(os.path.abspath(file_path))
            if normalized_path not in seen:
                seen.add(normalized_path)
                bat_files.append(file_path)

    results = []
    command_processor = os.environ.get("COMSPEC", "cmd.exe")

    for file_path in bat_files:
        try:
            completed = subprocess.run(
                [command_processor, "/c", file_path],
                check=False,
            )
            exit_code = completed.returncode
        except (OSError, subprocess.SubprocessError):
            exit_code = None

        results.append((os.path.basename(file_path), exit_code))

    return results

import subprocess
import os
import shutil
from glob import glob


def task_func(src_folder, dst_folder):
    failed_files = []

    if not os.path.isdir(src_folder):
        return {
            "success": False,
            "message": "Source folder does not exist or is not a directory.",
            "failed_files": [],
        }

    if os.path.exists(dst_folder) and not os.path.isdir(dst_folder):
        return {
            "success": False,
            "message": "Destination path exists but is not a directory.",
            "failed_files": [],
        }

    try:
        os.makedirs(dst_folder, exist_ok=True)
    except OSError as exc:
        return {
            "success": False,
            "message": f"Could not create destination folder: {exc}",
            "failed_files": [],
        }

    source_files = [
        path
        for path in glob(os.path.join(src_folder, "*"))
        if os.path.isfile(path)
    ]

    if not source_files:
        return {
            "success": True,
            "message": "No files found to compress.",
            "failed_files": [],
        }

    jobs = []

    for index, source_path in enumerate(source_files):
        filename = os.path.basename(source_path)
        temp_path = os.path.join(
            dst_folder,
            f".{filename}.{os.getpid()}.{index}.tmp",
        )
        output_file = None

        try:
            file_descriptor = os.open(
                temp_path,
                os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            )
            output_file = os.fdopen(file_descriptor, "wb")
            process = subprocess.Popen(
                ["gzip", "-c", source_path],
                stdout=output_file,
                stderr=subprocess.DEVNULL,
            )
            jobs.append((filename, temp_path, output_file, process))
        except (OSError, subprocess.SubprocessError):
            failed_files.append(filename)
            if output_file is not None:
                try:
                    output_file.close()
                except OSError:
                    pass
            try:
                os.remove(temp_path)
            except OSError:
                pass

    completed = []

    for filename, temp_path, output_file, process in jobs:
        try:
            process.wait()
            output_file.close()

            if process.returncode != 0:
                failed_files.append(filename)
                os.remove(temp_path)
            else:
                completed.append((filename, temp_path))
        except (OSError, subprocess.SubprocessError):
            failed_files.append(filename)
            try:
                output_file.close()
            except OSError:
                pass
            try:
                os.remove(temp_path)
            except OSError:
                pass

    for filename, temp_path in completed:
        destination_path = os.path.join(dst_folder, filename + ".gz")
        try:
            shutil.move(temp_path, destination_path)
        except OSError:
            failed_files.append(filename)
            try:
                os.remove(temp_path)
            except OSError:
                pass

    if failed_files:
        return {
            "success": False,
            "message": f"{len(failed_files)} file(s) failed to compress or move.",
            "failed_files": failed_files,
        }

    return {
        "success": True,
        "message": "All files were compressed and moved successfully.",
        "failed_files": [],
    }

