import numpy as np
import random


def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    if isinstance(MIN_WORDS, (bool, np.bool_)) or isinstance(
        MAX_WORDS, (bool, np.bool_)
    ):
        raise ValueError("MIN_WORDS and MAX_WORDS must be integers.")

    if not isinstance(MIN_WORDS, (int, np.integer)) or not isinstance(
        MAX_WORDS, (int, np.integer)
    ):
        raise ValueError("MIN_WORDS and MAX_WORDS must be integers.")

    MIN_WORDS = int(MIN_WORDS)
    MAX_WORDS = int(MAX_WORDS)

    if MIN_WORDS < 0 or MIN_WORDS > MAX_WORDS:
        raise ValueError("Invalid word-count range.")

    if isinstance(WORDS_POOL, (str, bytes)):
        raise ValueError("WORDS_POOL must be a collection of words.")

    try:
        pool = tuple(WORDS_POOL)
    except TypeError as exc:
        raise ValueError("WORDS_POOL must be a collection of words.") from exc

    if MAX_WORDS > 0:
        if not pool:
            raise ValueError("WORDS_POOL must not be empty.")
        if any(
            not isinstance(word, str) or not word or any(word.isspace() for _ in [0])
            or len(word.split()) != 1
            for word in pool
        ):
            raise ValueError("WORDS_POOL must contain single non-empty words.")

    length = random.randint(MIN_WORDS, MAX_WORDS)

    if length == 0:
        return ""

    first_half = [random.choice(pool) for _ in range(length // 2)]
    words = first_half[:]

    if length % 2:
        words.append(random.choice(pool))

    words.extend(reversed(first_half))
    return " ".join(words)

