STOPWORDS = set(stopwords.words('english'))
def task_func(text, n=2):
    """Remove duplicate non-stopword tokens and count contiguous n-grams."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if isinstance(n, bool) or not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")

    tokens = re.findall(r"\b\w+\b", text.lower())
    unique_tokens = list(dict.fromkeys(
        token for token in tokens if token not in STOPWORDS
    ))

    ngrams = (
        tuple(unique_tokens[i:i + n])
        for i in range(len(unique_tokens) - n + 1)
    )
    return dict(Counter(ngrams))

