import socket
from ipaddress import IPv4Network
from threading import Thread


def task_func(ip_range, port):
    """Return TCP port availability for each host in an IPv4 network."""

    network = IPv4Network(ip_range, strict=False)

    if not isinstance(port, int) or isinstance(port, bool):
        raise TypeError("port must be an integer")
    if not 1 <= port <= 65535:
        raise ValueError("port must be between 1 and 65535")

    results = {}

    def scan(ip):
        address = str(ip)
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
                sock.settimeout(1.0)
                results[address] = sock.connect_ex((address, port)) == 0
        except OSError:
            results[address] = False

    threads = [Thread(target=scan, args=(ip,)) for ip in network.hosts()]

    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()

    return results

import numpy as np
import itertools

def task_func(data_list, file_name):
    if not data_list:
        with open(file_name, "w"):
            pass
        return []

    max_length = max(len(item) for item in data_list)
    value_count = max(0, max_length - 1)
    padded_values = []

    for item in data_list:
        values = item[1:] if len(item) > 1 else ()
        padded_values.append(
            list(itertools.islice(
                itertools.chain(values, itertools.repeat(np.nan)),
                value_count
            ))
        )

    means = []
    for column in zip(*padded_values):
        numeric_values = []

        for value in column:
            try:
                numeric_values.append(float(value))
            except (TypeError, ValueError):
                numeric_values.append(np.nan)

        if np.all(np.isnan(numeric_values)):
            means.append(np.nan)
        else:
            means.append(float(np.nanmean(numeric_values)))

    with open(file_name, "w") as file:
        for position, mean in enumerate(means, start=1):
            file.write(f"Position {position}: {mean}\n")

    return means

