import subprocess
import time
import json
import platform
import re

LOGFILE_PATH = "logfile.log"


def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")

    system = platform.system()

    if system == "Windows":
        command = ["wmic", "cpu", "get", "loadpercentage", "/value"]
    elif system == "Linux":
        command = ["top", "-bn1"]
    else:
        raise OSError(f"Unsupported platform: {system}")

    records = []
    start_time = time.time()

    while time.time() - start_time <= duration:
        try:
            result = subprocess.run(
                command,
                capture_output=True,
                text=True,
                check=True,
            )
            output = result.stdout
            usage = None

            if system == "Windows":
                match = re.search(
                    r"LoadPercentage\s*=\s*(\d+(?:\.\d+)?)",
                    output,
                    re.IGNORECASE,
                )
                if match is None:
                    match = re.search(r"\b(\d+(?:\.\d+)?)\b", output)
                if match:
                    usage = float(match.group(1))
            else:
                match = re.search(r"(\d+(?:\.\d+)?)\s*id\b", output)
                if match:
                    usage = 100.0 - float(match.group(1))

            if usage is not None:
                records.append(
                    {
                        "timestamp": time.strftime(
                            "%Y-%m-%dT%H:%M:%S",
                            time.localtime(),
                        ),
                        "cpu_usage": max(0.0, min(100.0, usage)),
                    }
                )
        except (subprocess.SubprocessError, OSError, ValueError):
            pass

        if time.time() - start_time >= duration:
            break

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, "w", encoding="utf-8") as logfile:
            json.dump(records, logfile, indent=2)
    except OSError:
        return None

    return LOGFILE_PATH

