def task_func(json_data: str, key_path: list):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("JSON data must be a non-empty string.")

    if not isinstance(key_path, list) or not key_path:
        raise ValueError("Key path must be a non-empty list.")

    try:
        data = json.loads(
            json_data,
            parse_constant=lambda value: (_ for _ in ()).throw(
                ValueError(f"Invalid JSON constant: {value}")
            ),
        )
    except (json.JSONDecodeError, TypeError, ValueError):
        raise ValueError("Invalid or corrupted JSON data.") from None

    current = data
    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(key)
        current = current[key]

    values = []

    def collect_numeric(value):
        if isinstance(value, bool):
            return
        if isinstance(value, (int, float)):
            values.append(value)
        elif isinstance(value, dict):
            for nested_value in value.values():
                collect_numeric(nested_value)
        elif isinstance(value, list):
            for nested_value in value:
                collect_numeric(nested_value)

    collect_numeric(current)

    if not values:
        raise ValueError("No numeric data found.")

    dataframe = pd.DataFrame({"value": np.asarray(values, dtype=float)})

    figure, axis = plt.subplots()
    sns.boxplot(data=dataframe, y="value", ax=axis)
