                socket.inet_pton(address_family, ip_address)
                valid = True
                break
            except (OSError, ValueError):
                continue

        if not valid:
            continue

        try:
            result[ip_address] = socket.gethostbyaddr(ip_address)[0]
        except (socket.herror, socket.gaierror, OSError):
            result[ip_address] = None

    return result

