import numpy as np
from sympy import symbols, solve

def task_func(precision=2, seed=0):
    if isinstance(precision, bool) or not isinstance(precision, int) or precision < 0:
        raise ValueError("precision must be a non-negative integer")

    np.random.seed(seed)
    a, b, c = np.random.randint(-10, 11, size=3)

    while a == 0:
        a = np.random.randint(-10, 11)

    x = symbols("x")
    roots = solve(a * x**2 + b * x + c, x)

    if len(roots) == 1:
        roots *= 2

    result = []
    for root in roots[:2]:
        value = complex(root.evalf())
        result.append(
            complex(
                round(value.real, precision),
                round(value.imag, precision),
            )
        )

    return tuple(result)

