                )

                if os.path.commonpath(
                    (extraction_dir, member_path)
                ) != extraction_dir:
                    raise tarfile.TarError("Unsafe archive path")

            archive.extractall(path=extraction_dir)

        return True

    except Exception:
        try:
            if os.path.exists(TARGET_TAR_FILE):
                os.remove(TARGET_TAR_FILE)
