    x_future = np.arange(sales.size, 2 * sales.size, dtype=float).reshape(-1, 1)

    model = LinearRegression()
    model.fit(x_train, sales)

    return np.asarray(model.predict(x_future), dtype=float)

import re
import glob
from docx import Document


def task_func(directory_path: str) -> int:
    docx_files = glob.glob(f"{directory_path}/*.docx")

    def process_paragraph(paragraph) -> None:
        for run in paragraph.runs:
            run.text = run.text.replace('"', r'\"')

    def process_container(container, seen: set[int]) -> None:
        element_id = id(container._element)
        if element_id in seen:
            return
        seen.add(element_id)

        for paragraph in container.paragraphs:
            process_paragraph(paragraph)

        for table in container.tables:
            for row in table.rows:
                for cell in row.cells:
                    process_container(cell, seen)

    processed = 0

    for file_path in docx_files:
        document = Document(file_path)
        seen: set[int] = set()

        process_container(document, seen)

        for section in document.sections:
            for container in (
                section.header,
                section.first_page_header,
                section.even_page_header,
                section.footer,
                section.first_page_footer,
                section.even_page_footer,
            ):
                process_container(container, seen)

        document.save(file_path)
        processed += 1

    return processed

