import random


def task_func(colors, states):
    num_columns = min(len(colors), len(states))

    if num_columns == 0:
        return pd.DataFrame()

    combinations = [
        f"{color}:{state}"
        for color, state in itertools.product(colors, states)
    ]
    random.shuffle(combinations)

    base_size, remainder = divmod(len(combinations), num_columns)
    columns = {}
    start = 0

    for index in range(num_columns):
        size = base_size + (index < remainder)
        columns[index] = combinations[start:start + size]
        start += size

    return pd.DataFrame(columns)

