    contents = filtered["content"].fillna("").astype(str).tolist()

    try:
        vectors = CountVectorizer().fit_transform(contents)
    except ValueError:
        return [0] * len(contents)

    if len(contents) == 1:
        return [0]

    return KMeans(
        n_clusters=min(2, len(contents)),
        random_state=42,
        n_init=10,
    ).fit_predict(vectors).tolist()

import binascii
import hashlib
import re
import os

OUTPUT_DIR = './output'


def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    matcher = re.compile(pattern)
    hashes = {}

    for root, _, filenames in os.walk(directory):
        for filename in filenames:
            file_path = os.path.join(root, filename)

            if not matcher.search(file_path):
                continue
            if os.path.islink(file_path) or not os.path.isfile(file_path):
                continue

            digest = hashlib.sha256()
            with open(file_path, "rb") as file:
                for chunk in iter(lambda: file.read(1024 * 1024), b""):
                    digest.update(chunk)

            hashes[file_path] = binascii.hexlify(digest.digest()).decode("ascii")

    return hashes

import re
import json
import requests


def task_func(data_url: str) -> list:
    try:
        response = requests.get(data_url)
        payload = response.text
        json.loads(payload)

        filtered = []
        array_depth = 0
        in_string = False
        escaped = False

        for char in payload:
            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False

                if array_depth == 0:
                    filtered.append(char)
                continue

            if char == '"':
                in_string = True
                if array_depth == 0:
                    filtered.append(char)
            elif char == "[":
                array_depth += 1
            elif char == "]":
                if array_depth > 0:
                    array_depth -= 1
            elif array_depth == 0:
                filtered.append(char)

        pattern = r'"name"\s*:\s*"((?:\\.|[^"\\])*)"'
        matches = re.findall(pattern, "".join(filtered))

        return [json.loads(f'"{match}"') for match in matches]

    except Exception:
        return "Invalid url input"

