import numpy as np
from sklearn.cluster import KMeans
import matplotlib.pyplot as plt


def task_func(
    P: np.ndarray,
    T: np.ndarray,
    n_clusters: int = 3,
    random_state: int = 0,
    n_init: int = 10,
) -> (np.ndarray, plt.Axes):
    if not isinstance(P, np.ndarray) or P.ndim != 2:
        raise ValueError("P must be a 2D NumPy array.")
    if not isinstance(T, np.ndarray) or T.ndim != 3:
        raise ValueError("T must be a 3D NumPy array.")
    if P.shape[1] != T.shape[0]:
        raise ValueError(
            "The number of columns in P must equal the first dimension of T."
        )
    if P.size == 0 or T.size == 0:
        raise ValueError("P and T must not be empty.")
    if not np.issubdtype(P.dtype, np.number) or not np.issubdtype(
        T.dtype, np.number
    ):
        raise ValueError("P and T must contain numeric values.")
    if not np.isfinite(P).all() or not np.isfinite(T).all():
        raise ValueError("P and T must contain only finite values.")
    if not isinstance(n_clusters, (int, np.integer)) or n_clusters < 1:
        raise ValueError("n_clusters must be a positive integer.")
    if not isinstance(n_init, (int, np.integer)) or n_init < 1:
        raise ValueError("n_init must be a positive integer.")

    product = np.tensordot(P, T, axes=([1], [0]))
    flattened = product.ravel()

    if n_clusters > flattened.size:
        raise ValueError(
            "n_clusters cannot exceed the number of flattened samples."
        )

    cluster_result = KMeans(
        n_clusters=n_clusters,
        random_state=random_state,
        n_init=n_init,
    ).fit_predict(flattened.reshape(-1, 1))

    _, ax = plt.subplots()
    ax.scatter(
        np.arange(flattened.size),
        flattened,
        c=cluster_result,
        cmap="viridis",
    )
    ax.set_title("KMeans Clustering Visualization")
    ax.set_xlabel("Flattened Index")
    ax.set_ylabel("Value")

    return cluster_result, ax

