import os
import shutil

# Constants
BACKUP_DIR = '/tmp/backup'


def task_func(directory):
    directory = os.path.abspath(directory)

    if not os.path.isdir(BACKUP_DIR):
        return f'Backup directory {BACKUP_DIR} does not exist. Cannot rollback update.'

    directory_name = os.path.basename(os.path.normpath(directory))
    backup_path = os.path.join(BACKUP_DIR, directory_name)

    if not os.path.isdir(backup_path):
        return f'Backup for directory {directory} does not exist. Cannot rollback update.'

    if os.path.realpath(directory) == os.path.realpath(backup_path):
        return f'Cannot rollback directory {directory} because it is the backup source.'

    try:
        if os.path.lexists(directory):
            if os.path.isdir(directory) and not os.path.islink(directory):
                shutil.rmtree(directory)
            else:
                os.remove(directory)

        shutil.copytree(backup_path, directory)
    except OSError as error:
        return f'Failed to restore directory {directory}: {error}'

    return directory

