from typing import List, Union
import numpy as np
import scipy.fft


def task_func(data: List[Union[int, str]], repetitions: int = 1):
    if not data or repetitions <= 0:
        return {
            "mode": np.array([]),
            "count": np.array([]),
        }

    frequencies = {}
    for value in data:
        frequencies[value] = frequencies.get(value, 0) + 1

    maximum_count = max(frequencies.values())
    modes = [value for value, count in frequencies.items() if count == maximum_count]

    try:
        modes.sort()
    except TypeError as exc:
        raise TypeError("All mode values must be mutually comparable.") from exc

    return {
        "mode": np.array(modes),
        "count": np.full(len(modes), maximum_count * repetitions, dtype=int),
    }

import numpy as np
import pandas as pd
from numbers import Real


def task_func(
    products,
    n_samples=100,
    sales_lower=50,
    sales_upper=200,
    profit_margin_min=0.1,
    profit_margin_max=0.5,
    random_seed=42,
):
    if not isinstance(products, list) or not all(
        isinstance(product, str) for product in products
    ):
        raise TypeError("products must be a list of strings")

    if (
        isinstance(n_samples, bool)
        or not isinstance(n_samples, (int, np.integer))
        or n_samples <= 0
    ):
        raise ValueError("n_samples must be a positive integer")

    parameters = (
        sales_lower,
        sales_upper,
        profit_margin_min,
        profit_margin_max,
    )
    if any(
        isinstance(value, bool) or not isinstance(value, Real)
        for value in parameters
    ):
        raise TypeError("Sales and profit margin parameters must be numeric")

    if sales_lower > sales_upper:
        raise ValueError("sales_lower cannot be greater than sales_upper")

    if profit_margin_min > profit_margin_max:
        raise ValueError("profit_margin_min cannot be greater than profit_margin_max")

    columns = ["Product", "Total Sales", "Total Profit"]

    if not products:
        return pd.DataFrame(columns=columns)

    rng = np.random.default_rng(random_seed)

    sampled_products = rng.choice(products, size=n_samples)
    sales = rng.uniform(sales_lower, sales_upper, size=n_samples)
    margins = rng.uniform(
        profit_margin_min, profit_margin_max, size=n_samples
    )

    transactions = pd.DataFrame(
        {
            "Product": sampled_products,
            "Sales": sales,
            "Profit": sales * margins,
        }
    )

    report = (
        transactions.groupby("Product", as_index=False)
        .agg(
            **{
                "Total Sales": ("Sales", "sum"),
                "Total Profit": ("Profit", "sum"),
            }
        )
    )

    unique_products = pd.Index(products).drop_duplicates()
    report = (
        report.set_index("Product")
        .reindex(unique_products, fill_value=0)
        .rename_axis("Product")
        .reset_index()
    )

    return report.sort_values(
        "Total Profit",
        ascending=False,
        kind="mergesort",
    ).reset_index(drop=True)

