            isinstance(value, bool)
            or not isinstance(value, (int, np.integer))
            for value in sublist
        ):
            raise TypeError("L must be a list of lists of integers")

    arrays = [np.asarray(sublist) for sublist in L if sublist]

    if not arrays:
        values = np.array([], dtype=int)
        bins = 1
    else:
        values = np.concatenate(arrays)
        unique_values = np.unique(values)

        if unique_values.size == 1:
            value = unique_values[0]
            bins = np.array([value - 0.5, value + 0.5])
        else:
            midpoints = (unique_values[:-1] + unique_values[1:]) / 2
            bins = np.concatenate(
                (
                    [unique_values[0] - 0.5],
                    midpoints,
                    [unique_values[-1] + 0.5],
                )
            )

    return pd.Series(values).hist(bins=bins, rwidth=0.8)

