import os
import sys
import importlib
from pkgutil import iter_modules


def task_func(package_name):
    if not isinstance(package_name, str) or not package_name.strip():
        raise ImportError(f"pip install {package_name}")

    try:
        package = importlib.import_module(package_name)
    except (ImportError, ModuleNotFoundError, ValueError, TypeError) as exc:
        raise ImportError(
            f"Unable to import {package_name}. Run: pip install {package_name}"
        ) from exc

    package_paths = getattr(package, "__path__", None)
    if package_paths is None:
        module_file = getattr(package, "__file__", None)
        search_paths = [os.path.dirname(module_file)] if module_file else []
    else:
        search_paths = list(package_paths)

    modules = []
    seen = set()

    for path in search_paths:
        if path not in sys.path:
            sys.path.append(path)

        for module_info in iter_modules([path]):
            if module_info.name not in seen:
                seen.add(module_info.name)
                modules.append(module_info.name)

    return modules

