import random
import re


def task_func(text, seed=None):
    rng = random.Random(seed)

    def scramble(match):
        word = match.group(0)
        if len(word) <= 3:
            return word

        middle = list(word[1:-1])
        rng.shuffle(middle)
        return word[0] + "".join(middle) + word[-1]

    return re.sub(r"\b\w+\b", scramble, text)

import subprocess
import os
import time
import glob


def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    success_message = "File generated successfully within the specified duration."
    failure_message = "File not generated within the specified duration."

    if duration < 0 or not os.path.isfile(r_script_path):
        return False, failure_message

    def matching_files():
        paths = set(glob.glob(output_path))
        if os.path.isfile(output_path):
            paths.add(output_path)
        return paths

    def file_signature(path):
        try:
            stat = os.stat(path)
            return stat.st_mtime_ns, stat.st_size, stat.st_ino
        except OSError:
            return None

    initial_files = {
        path: file_signature(path)
        for path in matching_files()
        if os.path.isfile(path)
    }

    process = None
    deadline = time.monotonic() + duration

    try:
        try:
            process = subprocess.Popen(
                ["Rscript", r_script_path],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
        except OSError:
            return False, failure_message

        while time.monotonic() <= deadline:
            current_files = matching_files()
            for path in current_files:
                signature = file_signature(path)
                if signature is not None and (
                    path not in initial_files
                    or signature != initial_files[path]
                ):
                    return True, success_message

            if process.poll() is not None:
                break

            remaining = deadline - time.monotonic()
            if remaining > 0:
                time.sleep(min(0.05, remaining))

        return False, failure_message
    finally:
        if process is not None and process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()

