import re
import matplotlib.pyplot as plt
from nltk.probability import FreqDist


def task_func(example_str, top_n=30):
    if not isinstance(example_str, str):
        raise TypeError("example_str must be a string")
    if not isinstance(top_n, int) or isinstance(top_n, bool) or top_n < 0:
        raise ValueError("top_n must be a non-negative integer")

    visible_text = []
    bracket_depth = 0

    for char in example_str:
        if char == "[":
            bracket_depth += 1
        elif char == "]":
            if bracket_depth > 0:
                bracket_depth -= 1
            else:
                visible_text.append(char)
        elif bracket_depth == 0:
            visible_text.append(char)

    words = re.findall(
        r"\b\w+\b",
        "".join(visible_text).lower(),
        flags=re.UNICODE,
    )

    frequency_distribution = FreqDist(words)
    common_words = frequency_distribution.most_common(top_n)

    _, ax = plt.subplots()

    if common_words:
        labels, frequencies = zip(*common_words)
        ax.bar(labels, frequencies)
        ax.tick_params(axis="x", rotation=45)
        ax.figure.tight_layout()

    ax.set_title("Word Frequency Distribution")
    ax.set_xlabel("Words")
    ax.set_ylabel("Frequency")

    return ax, dict(common_words)

