def task_func(file_path: str) -> pd.DataFrame:
    columns = ["Timestamp", "Level", "Message"]
    pattern = re.compile(
        r"^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}\.\d{6})\s+-\s+(.+?)\s+-\s+(.*)$"
    )

    entries = []

