from scipy.stats import chi2_contingency


def task_func(df, columns=['A', 'B', 'C'], larger=50, equal=900):
    if len(columns) != 3:
        raise ValueError("Exactly three columns must be specified")

    if not all(column in df.columns for column in columns):
        raise ValueError("Specified columns must be contained in df")

    filtered = df[
        (df[columns[1]] > larger)
        & (df[columns[2]] == equal)
    ]

    if filtered.empty:
        raise ValueError("Insufficient data for the test")

    contingency_table = pd.crosstab(
        filtered[columns[0]],
        filtered[columns[1]],
    )

    _, p_value, _, _ = chi2_contingency(contingency_table)
    return float(p_value)

