import struct
import random
# Constants
KEYS = ['470FC614', '4A0FC614', '4B9FC614', '4C8FC614', '4D7FC614']


def task_func(hex_key=None):
    if hex_key is None:
        hex_key = random.choice(KEYS)

    if not isinstance(hex_key, str) or len(hex_key) != 8:
        raise ValueError("hex_key must be an 8-character hexadecimal string")

    try:
        raw_bytes = bytes.fromhex(hex_key)
    except ValueError as exc:
        raise ValueError("hex_key must contain only hexadecimal characters") from exc

    if len(raw_bytes) != 4:
        raise ValueError("hex_key must represent exactly 4 bytes")

    float_number = struct.unpack(">f", raw_bytes)[0]
    rounded_float = round(float_number, 2)

    return rounded_float

import numpy as np
from sklearn.preprocessing import MinMaxScaler
import pandas as pd


def task_func(df: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if df.empty:
        raise ValueError("DataFrame must not be empty")

    if not all(pd.api.types.is_numeric_dtype(dtype) for dtype in df.dtypes):
        raise TypeError("DataFrame must contain only numeric data")

    if df.isna().any().any():
        raise ValueError("DataFrame must not contain NaN values")

    cumulative = df.cumsum()
    normalized = MinMaxScaler().fit_transform(cumulative.to_numpy(dtype=float))

    return pd.DataFrame(
        normalized,
        index=df.index,
        columns=df.columns,
    )

import hashlib
import io
import os


def task_func(file_path1, file_path2):
    def calculate_md5(file_path):
        digest = hashlib.md5()
        with open(file_path, "rb") as file:
            for chunk in iter(lambda: file.read(8192), b""):
                digest.update(chunk)
        return digest.digest()

    return calculate_md5(file_path1) == calculate_md5(file_path2)

