import re
import os
import glob


def task_func(dir_path: str) -> list:
    files = [
        entry.path
        for entry in os.scandir(dir_path)
        if entry.is_file()
    ]

    renames = []
    targets = set()

    for old_path in files:
        old_name = os.path.basename(old_path)
        new_name = re.sub(r"[^A-Za-z0-9]", "", old_name)

        if not new_name:
            raise ValueError(f"Filename becomes empty: {old_name!r}")

        new_path = os.path.join(dir_path, new_name)
        target_key = os.path.normcase(os.path.abspath(new_path))

        if target_key in targets:
            raise FileExistsError(f"Filename collision: {new_name!r}")

        if new_path != old_path and os.path.exists(new_path):
            raise FileExistsError(f"Target already exists: {new_path!r}")

        targets.add(target_key)
        renames.append((old_path, new_path, new_name))

    result = []

    for old_path, new_path, new_name in renames:
        if old_path != new_path:
            os.rename(old_path, new_path)
        result.append(new_name)

    return result

