import numpy as np


def task_func(df):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("df must be a pandas DataFrame")

    if df.empty or df.shape[1] == 0:
        return np.array([], dtype=int)

    if not all(pd.api.types.is_numeric_dtype(dtype) for dtype in df.dtypes):
        raise ValueError("df must contain only numeric columns")

    if df.isna().any().any():
        raise ValueError("df must not contain missing values")

    scaled_data = StandardScaler().fit_transform(df)

    model = KMeans(
        n_clusters=min(3, len(df)),
        random_state=42,
        n_init=10,
    )

    return model.fit_predict(scaled_data)

import os
import requests
from zipfile import ZipFile, BadZipFile
import io


def task_func(url, download_path="mnt/data/downloads/"):
    try:
        response = requests.get(url, timeout=30)
        response.raise_for_status()
        content = response.content
    except requests.exceptions.RequestException:
        return "Error: Unable to download the file from the provided URL."

    try:
        content_type = response.headers.get("Content-Type", "")
        media_type = content_type.split(";", 1)[0].strip().lower()

        if media_type != "application/zip":
            return "Error: The URL does not point to a ZIP file."

        os.makedirs(download_path, exist_ok=True)

        try:
            with ZipFile(io.BytesIO(content)) as zip_file:
                zip_file.extractall(download_path)
        except (BadZipFile, OSError):
            return "Error: The downloaded file is not a valid ZIP file."

        return download_path
    except Exception as exc:
        return f"Error: {exc}"

