import re
from sklearn.feature_extraction.text import TfidfVectorizer


def task_func(texts):
    url_pattern = re.compile(r"(?:https?://|www\.)\S+", re.IGNORECASE)
    cleaned_texts = [
        url_pattern.sub("", text) if isinstance(text, str) else ""
        for text in texts
    ]

    if not cleaned_texts:
        return [], []

    vectorizer = TfidfVectorizer()

    try:
        matrix = vectorizer.fit_transform(cleaned_texts)
    except ValueError:
        return [tuple() for _ in cleaned_texts], []

    scores = [
        tuple(round(float(value), 8) for value in row)
        for row in matrix.toarray()
    ]
    features = vectorizer.get_feature_names_out().tolist()

    return scores, features

import os
import shutil


def task_func(path, delimiter="/"):
    if not isinstance(path, str) or not path.strip():
        raise ValueError("path must be a non-empty string")

    if not isinstance(delimiter, str) or not delimiter:
        raise ValueError("delimiter must be a non-empty string")

    components = path.split(delimiter)
    is_absolute = os.path.isabs(path)

    if is_absolute and components and components[0] == "":
        components = components[1:]

    if not components or any(
        not component or component in (".", "..") for component in components
    ):
        raise ValueError("path contains invalid components")

    current_path = os.path.sep if is_absolute else ""
    result = []

    for component in components:
        current_path = os.path.join(current_path, component)

        if not os.path.exists(current_path):
            raise FileNotFoundError(current_path)

        usage = shutil.disk_usage(current_path)
        result.append(
            (
                component,
                {
                    "total": usage.total,
                    "used": usage.used,
                    "free": usage.free,
                },
            )
        )

    return result

