import pandas as pd
from matplotlib import pyplot as plt
# Constants
TEAMS = ['Team A', 'Team B', 'Team C', 'Team D', 'Team E']
GOALS_RANGE = (-10, 10)


def task_func(goals, penalties):
    def get_values(values, name):
        if hasattr(values, "keys"):
            missing = [team for team in TEAMS if team not in values]
            if missing:
                raise ValueError(f"{name} is missing teams: {missing}")
            return [values[team] for team in TEAMS]

        if isinstance(values, (str, bytes)):
            raise ValueError(f"{name} must contain exactly five values")

        try:
            values = list(values)
        except TypeError as exc:
            raise ValueError(f"{name} must contain exactly five values") from exc

        if len(values) != len(TEAMS):
            raise ValueError(f"{name} must contain exactly five values")

        return values

    goal_values = get_values(goals, "goals")
    penalty_values = get_values(penalties, "penalties")

    scores = []
    for team, goal, penalty in zip(TEAMS, goal_values, penalty_values):
        if not pd.api.types.is_number(goal) or pd.isna(goal):
            raise ValueError(f"Invalid goal value for {team}: {goal!r}")
        if not pd.api.types.is_number(penalty) or pd.isna(penalty):
            raise ValueError(f"Invalid penalty value for {team}: {penalty!r}")

        try:
            score = goal - penalty
            score = max(GOALS_RANGE[0], min(GOALS_RANGE[1], score))
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"Goal and penalty values for {team} must be real numbers"
            ) from exc

        scores.append(score)

    result = pd.DataFrame({"Team": TEAMS, "Score": scores})

    plt.figure()
    plt.bar(result["Team"], result["Score"])
    plt.xlabel("Team")
    plt.ylabel("Score")
    plt.title("Adjusted Team Scores")
    plt.tight_layout()

    return result

import numpy as np
from difflib import SequenceMatcher
import matplotlib.pyplot as plt


def task_func(s_list, plot_path=None):
    if not isinstance(s_list, list) or not all(
        isinstance(item, str) for item in s_list
    ):
        raise ValueError("s_list must be a list of strings")

    if len(s_list) == 0:
        return []

    if len(s_list) == 1:
        scores = [np.nan]
    else:
        scores = [
            sum(
                SequenceMatcher(None, current, other).ratio()
                for j, other in enumerate(s_list)
                if i != j
            )
            / (len(s_list) - 1)
            for i, current in enumerate(s_list)
        ]

    if plot_path is not None:
        plt.figure()
        try:
            plt.plot(range(len(scores)), scores, marker="o")
            plt.xlabel("String index")
            plt.ylabel("Average similarity score")
            plt.title("Average Similarity Scores")
            plt.savefig(plot_path)
        finally:
            plt.close()

    return scores

from datetime import datetime
import pandas as pd
import numpy as np


def task_func(start_time, end_time, step, amplitude, period, seed=0):
    import matplotlib.pyplot as plt

    def to_utc(value, name):
        if not isinstance(value, datetime):
            raise ValueError(f"{name} must be a datetime")
        if value.tzinfo is None or value.utcoffset() is None:
            raise ValueError(f"{name} must be timezone-aware")
        return pd.Timestamp(value).tz_convert("UTC")

    start = to_utc(start_time, "start_time")
    end = to_utc(end_time, "end_time")

    if start > end:
        raise ValueError("start_time must not be later than end_time")

    if not isinstance(amplitude, (int, float, np.number)) or not np.isfinite(amplitude):
        raise ValueError("amplitude must be a finite number")
    if amplitude <= 0:
        raise ValueError("amplitude must be positive")

    if not isinstance(period, (int, float, np.number)) or not np.isfinite(period):
        raise ValueError("period must be a finite number")
    if period <= 0:
        raise ValueError("period must be positive")

    try:
        step_delta = pd.Timedelta(step)
    except (TypeError, ValueError):
        raise ValueError("step must be a valid positive time interval")

    if step_delta <= pd.Timedelta(0):
        raise ValueError("step must be positive")

    timestamps = pd.date_range(
        start=start,
        end=end,
        freq=step_delta,
        inclusive="both",
    )

    sample_indices = np.arange(len(timestamps))
    values = amplitude * np.sin(2 * np.pi * sample_indices / period)

    _, ax = plt.subplots()
    ax.plot(timestamps, values)
    ax.set_xlabel("Timestamp")
    ax.set_ylabel("Value")
    ax.set_title("Time Series with Seasonality")
    ax.grid(True)

    return ax

