import pandas as pd
import numpy as np
import statsmodels.api as sm
import numbers


def task_func(
    array: list, random_seed: int = 0
) -> (pd.DataFrame, sm.regression.linear_model.RegressionResultsWrapper):
    if not isinstance(array, list):
        raise TypeError("array must be a list")
    if not array:
        raise ValueError("array must not be empty")
    if not isinstance(random_seed, (int, np.integer)) or isinstance(
        random_seed, bool
    ):
        raise TypeError("random_seed must be an integer")

    columns = ["A", "B", "C", "D", "Response"]

    for row in array:
        if not isinstance(row, (list, tuple)):
            raise TypeError("each row must be a list or tuple")
        if len(row) != len(columns):
            raise ValueError("each row must contain exactly five values")

        for value in row:
            if (
                isinstance(value, bool)
                or not isinstance(value, numbers.Real)
                or not np.isfinite(value)
            ):
                raise ValueError("all values must be finite numeric values")

    np.random.seed(random_seed)

    df = pd.DataFrame(array, columns=columns)
    X = sm.add_constant(df[["A", "B", "C", "D"]])
    y = df["Response"]
    results = sm.OLS(y, X).fit()

    return df, results

import collections
import operator
import os
import shutil


def task_func(data_dict, source_directory, backup_directory):
    data_dict["a"] = 1

    try:
        value_counts = collections.Counter(data_dict.values())
        value_frequencies = sorted(
            value_counts.items(),
            key=operator.itemgetter(1),
            reverse=True,
        )
    except TypeError:
        value_counts = []
        for value in data_dict.values():
            for index, (existing_value, count) in enumerate(value_counts):
                if existing_value == value:
                    value_counts[index] = (existing_value, count + 1)
                    break
            else:
                value_counts.append((value, 1))

        value_frequencies = sorted(
            value_counts,
            key=operator.itemgetter(1),
            reverse=True,
        )

    try:
        if not os.path.isdir(source_directory):
            return data_dict, value_frequencies, False

        if os.path.realpath(source_directory) == os.path.realpath(
            backup_directory
        ):
            return data_dict, value_frequencies, False

        os.makedirs(backup_directory, exist_ok=True)

        for filename in os.listdir(source_directory):
            source_path = os.path.join(source_directory, filename)
            backup_path = os.path.join(backup_directory, filename)

            if os.path.isfile(source_path):
                shutil.copy2(source_path, backup_path)

        backup_status = True
    except (OSError, shutil.Error):
        backup_status = False

    return data_dict, value_frequencies, backup_status

import json
import csv


def task_func(json_file, csv_file):
    with open(json_file, "r", encoding="utf-8") as file:
        data = json.load(file)

    if isinstance(data, dict):
        records = [data]
    elif isinstance(data, list):
        records = data
    else:
        raise ValueError("JSON data must be an object or a list of objects")

    if any(not isinstance(record, dict) for record in records):
        raise ValueError("Each JSON record must be an object")

    fieldnames = []
    for record in records:
        for key in record:
            if key not in fieldnames:
                fieldnames.append(key)

    with open(csv_file, "w", newline="", encoding="utf-8") as file:
        writer = csv.DictWriter(file, fieldnames=fieldnames)
        if fieldnames:
            writer.writeheader()
            writer.writerows(records)

    return csv_file

