import re
import nltk
import pandas as pd
from sklearn.feature_extraction.text import CountVectorizer
# Make sure to download NLTK stopwords
nltk.download('stopwords')
# Define a regex pattern for matching all non-alphanumeric characters
ALPHANUMERIC = re.compile('[\W_]+')
# Load NLTK's list of English stop words
STOPWORDS = nltk.corpus.stopwords.words('english')


def task_func(texts):
    """Create a document-term matrix from text documents."""
    texts = list(texts)

    if any(not isinstance(text, str) for text in texts):
        raise TypeError("All documents must be strings.")

    def preprocess(text):
        return ALPHANUMERIC.sub(" ", text.lower())

    vectorizer = CountVectorizer(
        preprocessor=preprocess,
        stop_words=STOPWORDS,
    )

    try:
        matrix = vectorizer.fit_transform(texts)
    except ValueError as error:
        if "empty vocabulary" not in str(error).lower():
            raise
        return pd.DataFrame(index=range(len(texts)))

    return pd.DataFrame(
        matrix.toarray(),
        columns=vectorizer.get_feature_names_out(),
    )

import pandas as pd
