from random import randint, seed as random_seed


def task_func(
    start_date=datetime(2020, 1, 1),
    end_date=datetime(2020, 12, 31),
    seed=42,
):
    if not isinstance(start_date, datetime) or not isinstance(end_date, datetime):
        raise ValueError(
            "'start_date' and 'end_date' must be datetime.datetime instances"
        )

    if start_date > end_date:
        raise ValueError("'start_date' must not be later than 'end_date'")

    random_seed(seed)

    day_count = (end_date - start_date).days + 1
    dates = [
        start_date + timedelta(days=randint(0, day_count - 1))
        for _ in range(day_count)
    ]

    return pd.Series(dates)

import pandas as pd
import pytz


def task_func(articles, timezone):
    required_keys = {"category", "published_time"}

    if not isinstance(articles, list):
        raise TypeError("articles must be a list of dictionaries")

    if not articles:
        raise ValueError("articles must not be empty")

    if any(not isinstance(article, dict) for article in articles):
        raise TypeError("articles must be a list of dictionaries")

    if any(set(article.keys()) != required_keys for article in articles):
        raise ValueError(
            "Each article must contain exactly "
            "'category' and 'published_time' keys"
        )

    target_timezone = pytz.timezone(timezone)

    data = pd.DataFrame(articles)
    timestamps = pd.to_datetime(data["published_time"], utc=True)

    data["publication_hour"] = (
        timestamps.dt.tz_convert(target_timezone).dt.hour
    )

    result = (
        data.groupby("category")["publication_hour"]
        .agg(count="count", mean="mean", min="min", max="max")
    )

    result.index.name = "category"
    return result

