def task_func(file_name):
    with open(file_name, "r", newline="", encoding="utf-8") as file:
        reader = csv.reader(file)
        try:
            column_names = next(reader)
        except StopIteration:
            return {}

        if not column_names:
            return {}

        counters = [collections.Counter() for _ in column_names]
        has_data = False

        for row in reader:
            if not row:
                continue
            has_data = True
            for index, value in enumerate(row[:len(column_names)]):
                counters[index][value] += 1

        if not has_data:
            return {}

        result = {}
        for column_name, counter in zip(column_names, counters):
            if counter:
                highest_count = max(counter.values())
                candidates = [
                    value for value, count in counter.items()
                    if count == highest_count
                ]
                result[column_name] = min(candidates)
            else:
                result[column_name] = ""

        return result

