import pandas as pd
import re

# Function to replace acronyms in DataFrame
def task_func(data, mapping):
    result = data.copy()

    valid_mapping = {
        key: value
        for key, value in mapping.items()
        if isinstance(key, str) and key
    }

    if not valid_mapping:
        return result

    acronyms = sorted(valid_mapping, key=len, reverse=True)
    pattern = re.compile(
        r"(?<!\w)(?:" + "|".join(re.escape(acronym) for acronym in acronyms) + r")(?!\w)"
    )

    def replace_acronyms(value):
        if isinstance(value, str):
            return pattern.sub(
                lambda match: str(valid_mapping[match.group(0)]),
                value,
            )
        return value

    return result.apply(lambda column: column.map(replace_acronyms))

