import pandas as pd
import matplotlib.pyplot as plt
from statsmodels.tsa.seasonal import seasonal_decompose
import math


def task_func(df, freq='D', decomposition_model='multiplicative'):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    if "value" not in df.columns:
        raise ValueError("DataFrame must contain a 'value' column")

    if not isinstance(freq, str):
        raise ValueError("freq must be a valid frequency string")

    try:
        requested_offset = pd.tseries.frequencies.to_offset(freq)
    except (TypeError, ValueError):
        raise ValueError("freq must be a valid frequency string")

    if decomposition_model not in {"additive", "multiplicative"}:
        raise ValueError(
            "decomposition_model must be 'additive' or 'multiplicative'"
        )

    if not isinstance(df.index, pd.DatetimeIndex):
        raise ValueError("DataFrame index must be a DatetimeIndex")

    if df.empty:
        raise ValueError("DataFrame must not be empty")

    values = df["value"]
    if (
        not pd.api.types.is_numeric_dtype(values)
        or pd.api.types.is_bool_dtype(values)
        or pd.api.types.is_complex_dtype(values)
    ):
        raise ValueError("'value' column must contain numeric data")

    if values.isna().any():
        raise ValueError("'value' column contains invalid values")

    try:
        if not values.map(lambda value: math.isfinite(float(value))).all():
            raise ValueError("'value' column contains invalid values")
    except (TypeError, ValueError, OverflowError):
        raise ValueError("'value' column contains invalid values")

    if decomposition_model == "multiplicative" and (values <= 0).any():
        raise ValueError(
            "Multiplicative decomposition requires strictly positive values"
        )

    data = df[["value"]].copy().sort_index()

    if data.index.has_duplicates:
        raise ValueError("DataFrame index must not contain duplicates")

    inferred_frequency = pd.infer_freq(data.index)
    if inferred_frequency is None:
        raise ValueError("Could not infer the frequency of the index")

    try:
        inferred_offset = pd.tseries.frequencies.to_offset(inferred_frequency)
        if inferred_offset != requested_offset:
            raise ValueError("Index frequency does not match freq")
    except (TypeError, ValueError):
        raise ValueError("Index frequency does not match freq")

    rule = requested_offset.rule_code.upper()

    if rule.startswith("W"):
        period = 52
    elif rule in {"D", "B"}:
        period = 7 if rule == "D" else 5
    elif rule in {"H", "T", "MIN", "S"}:
        period = {"H": 24, "T": 60, "MIN": 60, "S": 60}[rule]
    elif rule in {"M", "ME"}:
        period = 12
    elif rule in {"Q", "QE"}:
        period = 4
    else:
        raise ValueError("Unsupported frequency for seasonal decomposition")

    if len(data) < 2 * period:
        raise ValueError("Insufficient observations for decomposition")

    try:
        result = seasonal_decompose(
            data["value"],
            model=decomposition_model,
            period=period,
            extrapolate_trend=False,
        )
        axes = result.plot().axes[0]
    except (TypeError, ValueError) as exc:
        raise ValueError("Unable to decompose the time series") from exc

    return result, axes

