import re
from datetime import time


def task_func(logs: list):
    timestamp_pattern = re.compile(
        r"(?<!\d)(?:[01]?\d|2[0-3]):[0-5]\d(?::[0-5]\d)?(?!\d)"
    )
    error_times = []

    for log in logs:
        if not isinstance(log, str) or not re.search(r"\berror\b", log, re.IGNORECASE):
            continue

        match = timestamp_pattern.search(log)
        if match is None:
            continue

        parts = [int(part) for part in match.group().split(":")]
        if len(parts) == 2:
            parts.append(0)

        error_times.append(time(*parts))

    if not error_times:
        return {"list": [], "time": None}

    total_seconds = sum(
        current.hour * 3600 + current.minute * 60 + current.second
        for current in error_times
    )
    average_seconds = round(total_seconds / len(error_times))

    return {
        "list": error_times,
        "time": time(
            average_seconds // 3600,
            (average_seconds % 3600) // 60,
            average_seconds % 60,
        ),
    }

import os
import re
from pathlib import Path


def task_func(dir_path: str, predicates: list) -> dict:
    directory = Path(dir_path)

    if not directory.is_dir():
        raise FileNotFoundError(f"Directory does not exist or is not a directory: {dir_path}")

    valid_predicates = []
    seen = set()

    for predicate in predicates or []:
        if isinstance(predicate, str):
            key = ("str", predicate)
            if key in seen:
                continue
            try:
                compiled = re.compile(predicate)
            except re.error:
                continue
        elif isinstance(predicate, re.Pattern):
            key = ("pattern", predicate.pattern, predicate.flags)
            if key in seen:
                continue
            compiled = predicate
        else:
            continue

        seen.add(key)
        valid_predicates.append(compiled)

    if not valid_predicates:
        raise ValueError("No valid predicates were provided")

    return {
        item_name: [
            predicate.search(item_name) is not None
            for predicate in valid_predicates
        ]
        for item_name in os.listdir(directory)
    }

