import pandas as pd
from numbers import Integral


def task_func(df, tuples, n_plots):
    if not isinstance(df, pd.DataFrame):
        raise ValueError("df must be a pandas DataFrame")

    if isinstance(n_plots, bool) or not isinstance(n_plots, Integral) or n_plots < 0:
        raise ValueError("n_plots must be a non-negative integer")

    try:
        conditions = list(tuples)
    except TypeError as exc:
        raise ValueError(
            "tuples must be an iterable of (column, value) pairs"
        ) from exc

    remove_mask = pd.Series(True, index=df.index)

    for condition in conditions:
        if not isinstance(condition, (tuple, list)) or len(condition) != 2:
            raise ValueError(
                "Each filtering condition must be a (column, value) pair"
            )

        column, value = condition

        if column not in COLUMNS:
            raise ValueError(f"Invalid column: {column}")
        if column not in df.columns:
            raise ValueError(f"Column not found in DataFrame: {column}")

        try:
            is_missing = pd.isna(value)
            is_missing = bool(is_missing) if not hasattr(is_missing, "__len__") else False
        except (TypeError, ValueError):
            is_missing = False

        if is_missing:
            condition_mask = df[column].isna()
        else:
            condition_mask = df[column].eq(value).fillna(False)

        remove_mask &= condition_mask

    filtered_df = df.loc[~remove_mask].copy()

    available_columns = [
        column for column in COLUMNS if column in filtered_df.columns
    ]
    pairs = [
        (available_columns[i], available_columns[j])
        for i in range(len(available_columns))
        for j in range(i + 1, len(available_columns))
    ]

    selected_pairs = sample(pairs, min(n_plots, len(pairs)))

    for x_column, y_column in selected_pairs:
        plt.figure()
        plt.plot(filtered_df[x_column], filtered_df[y_column])
        plt.xlabel(x_column)
        plt.ylabel(y_column)
        plt.title(f"{y_column} vs {x_column}")

    return filtered_df, selected_pairs

