import ast
import re


def task_func(text_file: str) -> list:
    with open(text_file, encoding="utf-8") as file:
        text = file.read()

    dictionaries = []
    position = 0

    while position < len(text):
        match = re.search(r"\{", text[position:])
        if match is None:
            break

        start = position + match.start()
        depth = 0
        quote = None
        escaped = False
        end = None

        for index in range(start, len(text)):
            char = text[index]

            if quote is not None:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    quote = None
                continue

            if char in ("'", '"'):
                quote = char
            elif char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    end = index + 1
                    break

        if end is None:
            position = start + 1
            continue

        try:
            value = ast.literal_eval(text[start:end])
            if isinstance(value, dict):
                dictionaries.append(value)
                position = end
                continue
        except (SyntaxError, ValueError, TypeError):
            pass

        position = start + 1

    return dictionaries

