def task_func(
    epoch_milliseconds,
    random_seed=0,
    products=["Product1", "Product2", "Product3", "Product4", "Product5"],
):
    if isinstance(epoch_milliseconds, bool) or not isinstance(
        epoch_milliseconds, (int, float)
    ):
        raise ValueError("epoch_milliseconds must be a numeric value.")

    try:
        if not math.isfinite(epoch_milliseconds) or epoch_milliseconds < 0:
            raise ValueError(
                "epoch_milliseconds must be finite and non-negative."
            )
    except OverflowError as exc:
        raise ValueError(
            "epoch_milliseconds must be finite and non-negative."
        ) from exc

    if not isinstance(products, (list, tuple)) or len(products) != 5:
        raise ValueError("products must contain exactly five product names.")

    if not all(isinstance(product, str) for product in products):
        raise ValueError("Each product name must be a string.")

    current_datetime = datetime.now()

    try:
        start_datetime = datetime.fromtimestamp(epoch_milliseconds / 1000)
    except (OverflowError, OSError, ValueError) as exc:
        raise ValueError("Invalid epoch_milliseconds value.") from exc

    if start_datetime > current_datetime:
        raise ValueError("epoch_milliseconds cannot represent a future time.")

    try:
        dates = pd.date_range(
            start=start_datetime.date(),
            end=current_datetime.date(),
            freq="D",
        )
    except (OverflowError, ValueError) as exc:
        raise ValueError("The date range is not supported.") from exc

