import os
import pandas as pd
from datetime import datetime


def task_func(
    excel_directory: str,
    file_name: str,
    column_name: str,
    start_date: str,
    end_date: str,
) -> pd.DataFrame:
    file_path = os.path.join(excel_directory, file_name)

    if not os.path.isfile(file_path):
        raise FileNotFoundError(f"Excel file not found: {file_path}")

    try:
        if not isinstance(start_date, str) or not isinstance(end_date, str):
            raise ValueError

        start = datetime.strptime(start_date, "%Y-%m-%d")
        end = datetime.strptime(end_date, "%Y-%m-%d")

        if start.strftime("%Y-%m-%d") != start_date:
            raise ValueError
        if end.strftime("%Y-%m-%d") != end_date:
            raise ValueError
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "start_date and end_date must use the YYYY-MM-DD format"
        ) from exc

    if start > end:
        raise ValueError("start_date cannot be later than end_date")

    dataframe = pd.read_excel(file_path)

    if column_name not in dataframe.columns:
        raise ValueError(f"Column does not exist: {column_name}")

    dates = pd.to_datetime(dataframe[column_name], errors="coerce")
    normalized_dates = dates.dt.normalize()
    mask = normalized_dates.between(start, end)

    return dataframe.loc[mask].copy()

