import socket
import select
import queue
from datetime import datetime, timedelta


def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    if buffer_size <= 0:
        raise ValueError("buffer_size must be greater than zero")

    duration = float(run_duration)
    start_time = datetime.now()
    deadline = start_time + timedelta(seconds=duration)

    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    clients = set()
    send_queues = {}
    pending_data = {}

    def close_client(client):
        clients.discard(client)
        send_queues.pop(client, None)
        pending_data.pop(client, None)
        try:
            client.close()
        except OSError:
            pass

    try:
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((server_address, server_port))
        server_socket.listen()
        server_socket.setblocking(False)

        while datetime.now() < deadline:
            remaining = (deadline - datetime.now()).total_seconds()
            timeout = max(0.0, min(remaining, 0.1))

            read_sockets = [server_socket, *clients]
            write_sockets = [
                client
                for client in clients
                if client in pending_data or not send_queues[client].empty()
            ]
            exceptional_sockets = [server_socket, *clients]

            try:
                readable, writable, exceptional = select.select(
                    read_sockets,
                    write_sockets,
                    exceptional_sockets,
                    timeout,
                )
            except InterruptedError:
                continue
            except (OSError, ValueError):
                break

            if server_socket in exceptional:
                break

            if server_socket in readable:
                while True:
                    client = None
                    try:
                        client, _ = server_socket.accept()
                        client.setblocking(False)
                        clients.add(client)
                        send_queues[client] = queue.Queue()
                    except BlockingIOError:
                        break
                    except InterruptedError:
                        if client is not None:
                            close_client(client)
                        continue
                    except OSError:
                        if client is not None:
                            close_client(client)
                        break

            for client in exceptional:
                if client is not server_socket and client in clients:
                    close_client(client)

            for client in list(readable):
                if client is server_socket or client not in clients:
                    continue

                try:
                    data = client.recv(buffer_size)
                    if not data:
                        close_client(client)
                        continue

                    timestamp = datetime.now().isoformat().encode("utf-8")
                    send_queues[client].put(data + timestamp)
                except (BlockingIOError, InterruptedError):
                    continue
                except (ConnectionResetError, BrokenPipeError, OSError, ValueError):
                    close_client(client)

            for client in list(writable):
                if client not in clients:
                    continue

                try:
                    if client not in pending_data:
                        pending_data[client] = send_queues[client].get_nowait()

                    sent = client.send(pending_data[client])
                    if sent <= 0:
                        close_client(client)
                    elif sent == len(pending_data[client]):
                        pending_data.pop(client, None)
                    else:
                        pending_data[client] = pending_data[client][sent:]
                except queue.Empty:
                    pending_data.pop(client, None)
                except (BlockingIOError, InterruptedError):
                    continue
                except (ConnectionResetError, BrokenPipeError, OSError, ValueError):
                    close_client(client)

    finally:
        for client in list(clients):
            close_client(client)

        try:
            server_socket.close()
        except OSError:
            pass

    elapsed = (datetime.now() - start_time).total_seconds()
    return f"Server ran for {elapsed:.2f} seconds"

import numpy as np
