def task_func(N=100, CATEGORIES=["A", "B", "C", "D", "E"], seed=42):
    if isinstance(N, bool) or not isinstance(N, (int, np.integer)):
        raise TypeError("N must be a non-negative integer")
    if N < 0:
        raise ValueError("N must be non-negative")

    categories = list(dict.fromkeys(CATEGORIES))

    if N > 0 and not categories:
        raise ValueError("CATEGORIES must not be empty when N > 0")

    rng = np.random.default_rng(seed)

    x = rng.random(N)
    y = rng.random(N)

    if N == 0:
        category_values = []
    elif N < len(categories):
        category_values = rng.choice(
            categories, size=N, replace=False
        ).tolist()
    else:
        category_values = categories.copy()
        category_values.extend(
            rng.choice(
                categories,
                size=N - len(categories),
                replace=True,
            ).tolist()
        )
        rng.shuffle(category_values)

    df = pd.DataFrame(
        {
            "x": x,
            "y": y,
            "category": category_values,
        }
    )

    _, ax = plt.subplots()

    if N > 0:
        colors = plt.colormaps["tab20"](
            np.linspace(0, 1, max(len(categories), 2))
        )

        for index, category in enumerate(categories):
            subset = df[df["category"] == category]
            ax.scatter(
                subset["x"],
                subset["y"],
                color=colors[index % len(colors)],
                label=str(category),
            )

        ax.legend()

    ax.set_xlabel("x")
    ax.set_ylabel("y")

    return df, ax

