def task_func(start_year=1980, end_year=2000, email_domain='example.com',
              latin_names=['Sopetón', 'Méndez', 'Gómez', 'Pérez', 'Muñoz'],
              other_names=['Smith', 'Johnson', 'Williams', 'Brown', 'Jones'],
              rng_seed=None):

    if isinstance(start_year, bool) or isinstance(end_year, bool):
        raise ValueError("Years must be integers.")
    if not isinstance(start_year, (int, np.integer)):
        raise ValueError("start_year must be an integer.")
    if not isinstance(end_year, (int, np.integer)):
        raise ValueError("end_year must be an integer.")

    start_year = int(start_year)
    end_year = int(end_year)

    if start_year < 0 or end_year < start_year or end_year > 9999:
        raise ValueError("Invalid year range.")

    if not isinstance(email_domain, str) or not email_domain:
        raise ValueError("email_domain must be a non-empty string.")

    try:
        supplied_names = list(latin_names) + list(other_names)
    except TypeError as exc:
        raise ValueError("Name collections must be iterable.") from exc

    if not supplied_names:
        raise ValueError("At least one name is required.")

    def repair_name(name):
        if not isinstance(name, str):
            raise ValueError("Names must be strings.")

        if re.search(r"[ÃÂâðÐÑ]", name):
            try:
                return codecs.decode(name.encode("latin1"), "utf-8")
            except (UnicodeEncodeError, UnicodeDecodeError):
                pass
        return name

    names = [repair_name(name) for name in supplied_names]
    rng = np.random.default_rng(rng_seed)

    selected_names = [
        str(name) for name in rng.choice(names, size=100)
    ]

    date_values = []
    emails = []

    for name in selected_names:
        year = int(rng.integers(start_year, end_year + 1))
        month = int(rng.integers(1, 13))

        if month == 2:
            is_leap_year = year % 400 == 0 or (
                year % 4 == 0 and year % 100 != 0
            )
            max_day = 29 if is_leap_year else 28
        elif month in (4, 6, 9, 11):
            max_day = 30
        else:
            max_day = 31

        day = int(rng.integers(1, max_day + 1))
        date_string = f"{year:04d}-{month:02d}-{day:02d} 00:00:00"

        if year == 0:
            date_values.append(date_string)
        else:
            date_values.append(
                datetime.datetime(year, month, day)
            )

        emails.append(f"{name.lower()}{year}@{email_domain}")

    return pd.DataFrame({
        "ID": np.arange(1, 101),
        "Name": selected_names,
        "Date of Birth": date_values,
        "Email": emails,
    })

