from sklearn.preprocessing import StandardScaler


def task_func(records: np.ndarray, random_seed: int = 0) -> pd.DataFrame:
    records = np.asarray(records)

    if records.ndim != 2:
        raise ValueError("records must be a 2D array")

    n_features = records.shape[1]
    feature_names = [f"f{i}" for i in range(1, n_features + 1)]

    permutation = np.random.RandomState(random_seed).permutation(n_features)
    shuffled_records = records[:, permutation]
    shuffled_names = [feature_names[i] for i in permutation]

    if records.shape[0] == 0 or n_features == 0:
        return pd.DataFrame(
            shuffled_records.astype(float),
            columns=shuffled_names,
        )

    normalized_records = StandardScaler().fit_transform(shuffled_records)
    return pd.DataFrame(normalized_records, columns=shuffled_names)

import os
import shutil
import string

# Constants
INVALID_CHARACTERS = string.punctuation + string.whitespace


def task_func(directory_path):
    if not os.path.isdir(directory_path):
        raise NotADirectoryError(directory_path)

    summary = {}

    def get_unique_destination(destination_dir, filename):
        destination_path = os.path.join(destination_dir, filename)
        if not os.path.exists(destination_path):
            return destination_path

        name, extension = os.path.splitext(filename)
        counter = 1
        while True:
            candidate = os.path.join(
                destination_dir,
                f"{name}_{counter}{extension}",
            )
            if not os.path.exists(candidate):
                return candidate
            counter += 1

    for filename in os.listdir(directory_path):
        source_path = os.path.join(directory_path, filename)

        if not os.path.isfile(source_path):
            continue

        if any(character in INVALID_CHARACTERS for character in filename):
            destination_name = "Invalid"
        else:
            _, extension = os.path.splitext(filename)
            destination_name = extension[1:] if extension else "No_extension"

        destination_dir = os.path.join(directory_path, destination_name)
        os.makedirs(destination_dir, exist_ok=True)

        destination_path = get_unique_destination(destination_dir, filename)
        shutil.move(source_path, destination_path)

        summary[destination_name] = summary.get(destination_name, 0) + 1

    return summary

