            "DataFrame must be non-empty and contain 'Title' and 'Content' columns."
        )

    title_pattern = re.compile(r"\b(?:like|what)\b", re.IGNORECASE)
    word_pattern = re.compile(r"[^\W_]+", re.UNICODE)
    frequencies = {}

    for _, row in df.iterrows():
        title = row["Title"]
        content = row["Content"]

        if not isinstance(title, str) or not title_pattern.search(title):
            continue
        if not isinstance(content, str):
            continue

        for word in word_pattern.findall(content.casefold()):
            frequencies[word] = frequencies.get(word, 0) + 1

    return frequencies

