import collections
from itertools import zip_longest
from random import choices


def task_func(l1, l2, K=10):
    if K < 0:
        raise ValueError("K must be non-negative")

    sentinel = object()
    combined = []

    for left, right in zip_longest(l1, l2, fillvalue=sentinel):
        if left is not sentinel:
            combined.append(left)
        if right is not sentinel:
            combined.append(right)

    if K == 0:
        return collections.Counter()

    if not combined:
        raise ValueError("Cannot sample from an empty combined list")

    return collections.Counter(choices(combined, k=K))

