import subprocess
import csv
import glob
import random
import os


def task_func(file):
    created_files = []

    def cleanup(pattern):
        for path in glob.glob(pattern):
            try:
                if os.path.isfile(path):
                    os.remove(path)
            except OSError:
                pass

    try:
        file_path = os.path.abspath(os.fspath(file))

        if not os.path.isfile(file_path) or not file_path.lower().endswith(".csv"):
            return []

        output_dir = os.path.dirname(file_path)
        token = f"{os.getpid()}_{random.randint(0, 10**9)}"
        prefix = os.path.join(output_dir, f"split_{token}_")

        while glob.glob(prefix + "*"):
            token = f"{os.getpid()}_{random.randint(0, 10**9)}"
            prefix = os.path.join(output_dir, f"split_{token}_")

        result = subprocess.run(
            ["split", "-l", "1000", file_path, prefix],
            check=False,
        )

        if result.returncode != 0:
            cleanup(prefix + "*")
            return []

        created_files = sorted(
            path for path in glob.glob(prefix + "*") if os.path.isfile(path)
        )

        if not created_files:
            return []

        for path in created_files:
            with open(path, "r", newline="") as source:
                lines = source.readlines()

            random.shuffle(lines)

            with open(path, "w", newline="") as target:
                target.writelines(lines)

        return created_files

    except (OSError, TypeError, ValueError, subprocess.SubprocessError):
        for path in created_files:
            try:
                os.remove(path)
            except OSError:
                pass
        return []

