import numpy as np

def task_func(samples=10, delay=0.1):
    if isinstance(samples, bool) or not isinstance(samples, (int, np.integer)):
        raise TypeError("samples must be an integer")
    if samples < 1:
        raise ValueError("samples must be at least 1")

    if isinstance(delay, bool) or not isinstance(
        delay, (int, float, np.integer, np.floating)
    ):
        raise TypeError("delay must be numeric")

    delay = float(delay)
    if not np.isfinite(delay) or delay < 0:
        raise ValueError("delay must be finite and non-negative")

    measured_delays = []
    for _ in range(samples):
        start = time.perf_counter()
        time.sleep(delay)
        measured_delays.append(time.perf_counter() - start)

    measurements = np.asarray(measured_delays, dtype=float)
    return float(np.mean(measurements)), float(np.std(measurements))

import re
