from pathlib import Path
import csv
import shutil


def task_func(directory: str, pattern: str = r'^(.*?)-\d+\.csv$') -> list:
    directory_path = Path(directory)

    if not directory_path.is_dir():
        raise NotADirectoryError(directory)

    regex = re.compile(pattern)

    if regex.groups == 0:
        raise ValueError("Pattern must contain at least one capture group")

    new_files = []

    for source_path in sorted(directory_path.iterdir(), key=lambda path: path.name):
        if not source_path.is_file() or source_path.suffix.lower() != ".csv":
            continue

        match = regex.fullmatch(source_path.name)
        if match is None:
            continue

        destination_name = f"{match.group(1)}.csv"
        destination_path = directory_path / destination_name

        if destination_path == source_path or destination_path.exists():
            continue

        shutil.copyfile(source_path, destination_path)
        new_files.append(destination_name)

    return sorted(new_files)

