import re
import pandas as pd


def task_func(df: pd.DataFrame, column_name: str, pattern: str) -> pd.DataFrame:
    if pattern == "":
        return df.copy()

    regex = re.compile(pattern)

    def reverse_matching_words(value):
        if not isinstance(value, str):
            return value

        words = value.split()
        matching_words = [
            word for word in words if regex.search(word)
        ][::-1]

        result = []
        match_index = 0

        for word in words:
            if regex.search(word):
                result.append(matching_words[match_index])
                match_index += 1
            else:
                result.append(word)

        return " ".join(result)

    result = df.copy()
    result[column_name] = result[column_name].map(reverse_matching_words)
    return result

