import json
import os
import re


def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str},
        },
        "required": ["name", "age", "email"],
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$",
):
    if not isinstance(file_path, (str, bytes, os.PathLike)) or not os.path.isfile(
        file_path
    ):
        raise ValueError("File does not exist")

    try:
        with open(file_path, "r", encoding="utf-8") as file:
            data = json.load(file)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("Unable to read or parse JSON file") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON root must be an object")

    required = INPUT_JSON.get("required", [])
    missing = [field for field in required if field not in data]
    if missing:
        raise ValueError(f"Missing required attributes: {missing}")

    properties = INPUT_JSON.get("properties", {})
    for field, definition in properties.items():
        if field not in data:
            continue

        expected_type = definition.get("type")
        value = data[field]

        if expected_type is int and isinstance(value, bool):
            raise ValueError(f"Invalid type for attribute: {field}")

        if not isinstance(value, expected_type):
            raise ValueError(f"Invalid type for attribute: {field}")

    if "email" not in data:
        raise ValueError("Missing required attribute: email")

    if re.fullmatch(EMAIL_REGEX, data["email"]) is None:
        raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute not found: {attribute}")

    return data[attribute]

