def task_func(rows=3, columns=2, start_date=datetime(2021, 1, 1), end_date=datetime(2021, 12, 31), seed=0):
    if not isinstance(rows, int) or isinstance(rows, bool):
        raise TypeError("rows must be an integer")
    if not isinstance(columns, int) or isinstance(columns, bool):
        raise TypeError("columns must be an integer")
    if rows < 0 or columns < 0:
        raise ValueError("rows and columns must be non-negative")

    if not isinstance(start_date, datetime) or not isinstance(end_date, datetime):
        raise TypeError("start_date and end_date must be datetime objects")
    if start_date > end_date:
        raise ValueError("start_date must not be later than end_date")

    count = rows * columns
    if count == 0:
        return np.empty((rows, columns), dtype=object)

    available = (end_date - start_date).days + 1
    if count > available:
        raise ValueError("date range does not contain enough unique dates")

    rng = random.Random(seed)
    offsets = rng.sample(range(available), count)
    dates = [start_date + timedelta(days=offset) for offset in offsets]

    return np.asarray(dates, dtype=object).reshape(rows, columns)

