import cgi
import http.server
import smtplib
from email.mime.text import MIMEText
import json


def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_response(self, status, message):
            body = message.encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            try:
                content_length = self.headers.get("Content-Length")
                if content_length is None:
                    raise ValueError("Missing Content-Length")

                try:
                    length = int(content_length)
                except (TypeError, ValueError):
                    raise ValueError("Invalid Content-Length")

                if length < 0:
                    raise ValueError("Invalid Content-Length")

                data = json.loads(self.rfile.read(length).decode("utf-8"))

                if not isinstance(data, dict):
                    raise ValueError("Email data must be an object")

                for key in ("subject", "message", "to"):
                    if key not in data:
                        raise ValueError(f"Missing field: {key}")

                if not all(
                    isinstance(data[key], str)
                    for key in ("subject", "message", "to")
                ):
                    raise ValueError("Email fields must be strings")

                message = MIMEText(data["message"], _charset="utf-8")
                message["Subject"] = data["subject"]
                message["From"] = smtp_username
                message["To"] = data["to"]

                smtp = smtplib.SMTP(smtp_server, smtp_port)
                try:
                    smtp.login(smtp_username, smtp_password)
                    smtp.sendmail(
                        smtp_username,
                        [data["to"]],
                        message.as_string(),
                    )
                finally:
                    try:
                        smtp.quit()
                    except Exception:
                        pass

                self._send_response(200, "Email sent")
            except (json.JSONDecodeError, UnicodeDecodeError, ValueError):
                self._send_response(400, "Bad Request")
            except smtplib.SMTPAuthenticationError:
                self._send_response(535, "Authentication Failed")

    return EmailRequestHandler

