def task_func(df, tuples, n_plots):
    import pandas as pd

    if isinstance(n_plots, bool) or not isinstance(n_plots, int) or n_plots < 0:
        raise ValueError("n_plots must be a non-negative integer")

    filtered_df = df.copy()
    row_patterns = [] if tuples is None else list(tuples)

    for row_values in row_patterns:
        if len(row_values) != len(df.columns):
            raise ValueError(
                "Each tuple must contain one value for every DataFrame column"
            )

    if row_patterns:
        remove_mask = pd.Series(False, index=df.index)

        for row_values in row_patterns:
            row_mask = pd.Series(True, index=df.index)

            for column, value in zip(df.columns, row_values):
                if pd.isna(value):
                    row_mask &= df[column].isna()
                else:
                    row_mask &= df[column].eq(value).fillna(False)

            remove_mask |= row_mask

        filtered_df = df.loc[~remove_mask].copy()

    column_pairs = list(combinations(filtered_df.columns, 2))
    selected_pairs = sample(column_pairs, min(n_plots, len(column_pairs)))

    plots = [
        (pair, filtered_df.plot.scatter(x=pair[0], y=pair[1]))
        for pair in selected_pairs
    ]

    return filtered_df, plots

