import re
import math

def task_func(s):
    number_pattern = re.compile(
        r"^[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$"
    )

    count = 0
    sqrt_sum = 0.0

    for item in s.split(","):
        item = item.strip()
        if not number_pattern.fullmatch(item):
            continue

        value = float(item)
        if value < 0:
            continue

        count += 1
        sqrt_sum += math.sqrt(value)

    return {"count": count, "sqrt_sum": sqrt_sum}

