def task_func(script_path: str, temp_dir: str) -> str:
    try:
        if not os.path.isfile(script_path):
            return "Script execution failed!"

        os.makedirs(temp_dir, exist_ok=True)

        source = os.path.abspath(script_path)
        destination = os.path.abspath(
            os.path.join(temp_dir, os.path.basename(script_path))
        )

        same_file = False
        if os.path.exists(destination):
            same_file = os.path.samefile(source, destination)

        if not same_file:
            shutil.copy2(source, destination)

        result = subprocess.run(
            [sys.executable, destination],
            cwd=temp_dir,
            check=False,
        )

        return (
            "Script executed successfully!"
            if result.returncode == 0
            else "Script execution failed!"
        )
    except Exception:
        return "Script execution failed!"

import subprocess
import psutil
import time


def task_func(process_name: str) -> str:
    matching_processes = []

    for process in psutil.process_iter(["name"]):
        try:
            if process.info["name"] == process_name:
                matching_processes.append(process)
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    if not matching_processes:
        subprocess.Popen(process_name, shell=True)
        return f"Process not found. Starting {process_name}."

    for process in matching_processes:
        try:
            process.terminate()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    time.sleep(0.1)

    for process in matching_processes:
        try:
            if process.is_running():
                process.kill()
        except (psutil.NoSuchProcess, psutil.AccessDenied):
            continue

    subprocess.Popen(process_name, shell=True)
    return f"Process found. Restarting {process_name}."

