import pandas as pd
import os
import json
from collections import Counter
import re


def task_func(json_dir_path, word_count):
    if not isinstance(json_dir_path, (str, os.PathLike)):
        raise TypeError("json_dir_path must be a path")

    if isinstance(word_count, bool) or not isinstance(word_count, int):
        raise TypeError("word_count must be an integer")

    if word_count <= 0:
        return []

    if not os.path.isdir(json_dir_path):
        raise ValueError("json_dir_path must refer to an existing directory")

    def extract_text(value):
        if isinstance(value, str):
            yield value
        elif isinstance(value, dict):
            for nested_value in value.values():
                yield from extract_text(nested_value)
        elif isinstance(value, list):
            for nested_value in value:
                yield from extract_text(nested_value)

    words = []

    with os.scandir(json_dir_path) as entries:
        json_files = sorted(
            (
                entry
                for entry in entries
                if entry.is_file()
                and os.fsdecode(entry.name).lower().endswith(".json")
            ),
            key=lambda entry: os.fsdecode(entry.name).lower(),
        )

        for entry in json_files:
            with open(entry.path, "r", encoding="utf-8") as file:
                data = json.load(file)

            for text in extract_text(data):
                words.extend(re.findall(r"\b\w+\b", text.lower(), flags=re.UNICODE))

    return Counter(words).most_common(word_count)

