import pandas as pd
from scipy.stats import pearsonr


def task_func(data):
    if len(data) < 2:
        return float("nan")

    columns = {str(column).strip().lower(): column for column in data.columns}
    score_column = columns.get("score")
    grade_column = columns.get("grade")

    if score_column is None or grade_column is None:
        if len(data.columns) < 2:
            return float("nan")
        score_column, grade_column = data.columns[:2]

    scores = pd.to_numeric(data[score_column], errors="coerce")
    scores = scores.replace([float("inf"), float("-inf")], float("nan"))

    grades = data[grade_column]

    if isinstance(grades.dtype, pd.CategoricalDtype) and grades.dtype.ordered:
        encoded_grades = grades.cat.codes.astype(float)
        encoded_grades = encoded_grades.replace(-1, float("nan"))
    else:
        categories = sorted(
            grades.dropna().unique(),
            key=lambda value: str(value),
        )
        encoding = {category: rank for rank, category in enumerate(categories)}
        encoded_grades = grades.map(encoding).astype(float)

    valid = scores.notna() & encoded_grades.notna()
    scores = scores[valid]
    encoded_grades = encoded_grades[valid]

    if (
        len(scores) < 2
        or scores.nunique() < 2
        or encoded_grades.nunique() < 2
    ):
        return float("nan")

    return float(pearsonr(scores, encoded_grades).statistic)

