        return 0

    if os.path.abspath(source_directory) == os.path.abspath(target_directory):
        return 0

    moved_count = 0

    for filename in os.listdir(source_directory):
        source_path = os.path.join(source_directory, filename)

        if not os.path.isfile(source_path) or not regex.search(filename):
            continue

        try:
            shutil.move(source_path, os.path.join(target_directory, filename))
        except (OSError, shutil.Error):
            continue

        moved_count += 1

    return moved_count

