import seaborn as sns
import pandas as pd

# Constants
COLUMNS = ['A', 'B', 'C', 'D', 'E']


def task_func(df: pd.DataFrame, tuples: list, n_plots: int) -> (pd.DataFrame, list):
    """Remove matching rows and generate random joint plots."""
    if not isinstance(n_plots, int) or n_plots < 0:
        raise ValueError("n_plots must be a non-negative integer")

    missing_columns = [column for column in COLUMNS if column not in df.columns]
    if missing_columns:
        raise ValueError(f"DataFrame is missing columns: {missing_columns}")

    filtered_df = df.copy()

    for values in tuples:
        if not hasattr(values, "__len__") or len(values) != len(COLUMNS):
            raise ValueError(
                f"Each filter tuple must contain {len(COLUMNS)} values"
            )

        matches = pd.Series(True, index=filtered_df.index)

        for column, value in zip(COLUMNS, values):
            if pd.isna(value):
                matches &= filtered_df[column].isna()
            else:
                matches &= filtered_df[column].eq(value)

        filtered_df = filtered_df.loc[~matches]

    if filtered_df.empty:
        return filtered_df, []

    plots = []
    for _ in range(n_plots):
        x_column, y_column = sample(COLUMNS, 2)
        plots.append(
            sns.jointplot(data=filtered_df, x=x_column, y=y_column)
        )

    return filtered_df, plots

