import sqlite3
import pandas as pd
import csv
from io import StringIO

# Constants
DATABASE_NAME = 'test.db'
TABLE_NAME = 'test_table'


def task_func(csv_input):
    """Import CSV data into SQLite and return it as a pandas DataFrame."""
    should_close = False

    if isinstance(csv_input, str) or hasattr(csv_input, "__fspath__"):
        source = open(csv_input, "r", encoding="utf-8-sig", newline="")
        should_close = True
    elif hasattr(csv_input, "read"):
        source = csv_input
    else:
        raise TypeError(
            "csv_input must be a file path or a text file-like object"
        )

    try:
        content = source.read()
        if not isinstance(content, str):
            raise TypeError("csv_input must provide text data")

        rows = list(csv.reader(StringIO(content), strict=True))

        while rows and not rows[-1]:
            rows.pop()

        if not rows:
            raise ValueError("CSV input is empty")

        headers = rows[0]
        if any(not header.strip() for header in headers):
            raise ValueError("CSV headers must not be empty")

        if len({header.casefold() for header in headers}) != len(headers):
            raise ValueError("CSV headers must be unique")

        data_rows = []
        for row_number, row in enumerate(rows[1:], start=2):
            if not row:
                continue
            if len(row) != len(headers):
                raise ValueError(
                    f"Row {row_number} has {len(row)} fields; "
                    f"expected {len(headers)}"
                )
            data_rows.append(row)

        def quote_identifier(identifier):
            if "\x00" in identifier:
                raise ValueError("Identifiers must not contain null characters")
            return '"' + identifier.replace('"', '""') + '"'

        table_name = quote_identifier(TABLE_NAME)
        column_names = [quote_identifier(header) for header in headers]

        with sqlite3.connect(DATABASE_NAME) as connection:
            connection.execute(f"DROP TABLE IF EXISTS {table_name}")

            columns = ", ".join(f"{name} TEXT" for name in column_names)
            connection.execute(f"CREATE TABLE {table_name} ({columns})")

            if data_rows:
                placeholders = ", ".join("?" for _ in headers)
                connection.executemany(
                    f"INSERT INTO {table_name} VALUES ({placeholders})",
                    data_rows,
                )

            return pd.read_sql_query(
                f"SELECT * FROM {table_name}",
                connection,
            )
    finally:
        if should_close:
            source.close()

