import numpy as np
from sklearn.preprocessing import StandardScaler
from sklearn.metrics import mean_squared_error


def task_func(num_samples=1000, k=5, d=2, random_seed=None):
    if not isinstance(num_samples, (int, np.integer)) or isinstance(num_samples, bool):
        raise ValueError("num_samples must be a positive integer")
    if num_samples <= 0:
        raise ValueError("num_samples must be a positive integer")

    if random_seed is not None:
        np.random.seed(random_seed)

    original = np.random.normal(0, 1, size=(num_samples, 1))
    transformed = k * original + d
    standardized = StandardScaler().fit_transform(transformed)

    return float(mean_squared_error(transformed, standardized))

